-- Login identity only. No legal name, address or mobile number.
IF OBJECT_ID(N'role', N'U') IS NULL
CREATE TABLE role (
    role_id BIGINT IDENTITY(1,1) PRIMARY KEY,
    role_name VARCHAR(50) NOT NULL UNIQUE
);

-- user_type: CUSTOMER or STAFF. For a customer the token's userId is customer_id;
-- for staff it is user_id. status: ACTIVE, INACTIVE.
IF OBJECT_ID(N'app_user', N'U') IS NULL
CREATE TABLE app_user (
    user_id BIGINT IDENTITY(1,1) PRIMARY KEY,
    role_id BIGINT NOT NULL REFERENCES role(role_id),
    user_type VARCHAR(20) NOT NULL CHECK (user_type IN ('CUSTOMER', 'STAFF')),
    customer_id BIGINT,
    username VARCHAR(100) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    email VARCHAR(150) NOT NULL UNIQUE,
    mfa_secret_ref VARCHAR(255),
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    created_at DATETIME2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
    CHECK ((user_type = 'CUSTOMER' AND customer_id IS NOT NULL) OR (user_type <> 'CUSTOMER' AND customer_id IS NULL))
